  "The link contains the whole card, so nothing is uploaded. Host the game online (for example GitHub Pages or Netlify) so friends can open the link.": "लिंक में पूरा कार्ड है, इसलिए कुछ भी अपलोड नहीं होता। गेम को ऑनलाइन होस्ट करें (जैसे GitHub Pages या Netlify) ताकि दोस्त लिंक खोल सकें।",
