  "Missed a day? Premium opens every past Daily Diya and Daily Rocket. Plus no ads and every cracker free.": "कोई दिन छूट गया? Premium हर पुराना डेली दीया और डेली रॉकेट खोल देता है। साथ में बिना विज्ञापन और हर पटाखा मुफ़्त।",
