  "Watch a video · double it": "वीडियो देखें · दोगुना करें",
  "Unlock all 1000 levels with Premium": "Premium के साथ सभी 1000 लेवल खोलें",
  "First {0} levels free · all 100 with Premium": "पहले {0} लेवल मुफ़्त · सभी 100 Premium के साथ",
  "🎁 Chest +{0}": "🎁 संदूक +{0}",
  "Diyas": "दीये",
