  "Kolam": "कोलम",
  "Golden diyas and royal boards": "सुनहरे दीये और शाही बोर्ड",
  "Premium dresses Diya Path in gold, with palace, river ghat and temple boards. Plus no ads and every cracker free.": "Premium दीया पथ को सोने से सजाता है, महल, नदी घाट और मंदिर के बोर्ड के साथ। साथ में बिना विज्ञापन और हर पटाखा मुफ़्त।",
  "Golden diyas & royal boards": "सुनहरे दीये और शाही बोर्ड",
  "All styles": "सभी स्टाइल",
  "India’s landmarks in 3D": "भारत के स्मारक 3D में",
  "Walk the forecourt of all 15 landmarks in 3D and look around as the fireworks burst. Plus no ads and every cracker free.": "सभी 15 स्मारकों के प्रांगण में 3D में घूमें और आतिशबाज़ी फूटते समय चारों ओर देखें। साथ में बिना विज्ञापन और हर पटाखा मुफ़्त।",
  "Fireworks in your room with AR": "AR के साथ अपने कमरे में आतिशबाज़ी",
  "Point your camera and light crackers on your own floor and sky. Plus no ads and every cracker free.": "कैमरा घुमाएँ और अपनी ही ज़मीन और आसमान पर पटाखे जलाएँ। साथ में बिना विज्ञापन और हर पटाखा मुफ़्त।",
  "Sacred backgrounds for Diya Path": "दीया पथ के लिए पावन पृष्ठभूमि",
  "Play before Lakshmi, Ganesha, Balaji, the Golden Temple and more. Plus no ads and every cracker free.": "लक्ष्मी, गणेश, बालाजी, स्वर्ण मंदिर और कई के सामने खेलें। साथ में बिना विज्ञापन और हर पटाखा मुफ़्त।",
  "Couldn’t load the plans from the store. Check you’re signed in and online, then try again.": "स्टोर से प्लान लोड नहीं हो सके। देखें कि आप साइन इन और ऑनलाइन हैं, फिर दोबारा कोशिश करें।",
  "See what Premium adds": "देखें Premium में क्या जुड़ता है",
  "Sacred backgrounds": "पावन पृष्ठभूमि",
  "Play Diya Path before Lakshmi, Ganesha, Balaji and more": "लक्ष्मी, गणेश, बालाजी और कई के सामने दीया पथ खेलें",
  "Sacred backgrounds: Lakshmi, Ganesha, Balaji and more": "पावन पृष्ठभूमि: लक्ष्मी, गणेश, बालाजी और कई",
  "All 10": "सभी 10",
  "AR fireworks and sparkler in your room": "आपके कमरे में AR आतिशबाज़ी और फुलझड़ी",
  "Free for everyone and included with every plan.": "सबके लिए मुफ़्त और हर प्लान में शामिल।",
  "AR pictures are illustrations; the look on your phone depends on your camera and room. AR crackers on your real floor need a phone that supports Google Play Services for AR.": "AR चित्र उदाहरण हैं; आपके फ़ोन पर रूप आपके कैमरे और कमरे पर निर्भर करता है। असली फ़र्श पर AR पटाखों के लिए Google Play Services for AR वाला फ़ोन चाहिए।",
  "15 landmarks in 3D, look around": "3D में 15 स्मारक, चारों ओर देखें",
