  "My Cards": "मेरे कार्ड",
  "Back to My Cards": "मेरे कार्ड पर वापस",
  "Play, change or send your cards again. They stay on this device.": "अपने कार्ड फिर से चलाएँ, बदलें या भेजें। ये इसी फ़ोन पर रहते हैं।",
  "Made": "बनाए",
  "Received": "मिले",
  "New card": "नया कार्ड",
  "Cards you make are kept here, ready to play, change or send again.": "आपके बनाए कार्ड यहाँ रहते हैं, फिर से चलाने, बदलने या भेजने के लिए तैयार।",
  "Cards friends send you are kept here, so you can watch them again.": "दोस्तों के भेजे कार्ड यहाँ रहते हैं, ताकि आप उन्हें फिर से देख सकें।",
  "Lit back": "जवाब में रोशनी",
  "Delete": "हटाएँ",
