  "May Lord Ganesha remove every obstacle and fill your life with joy. Happy Ganesh Chaturthi!": "भगवान गणेश हर विघ्न दूर करें और आपकी ज़िंदगी ख़ुशियों से भर दें। गणेश चतुर्थी की शुभकामनाएँ!",
