  "Chaos: points for the mischief your crackers cause (near people, stalls, roofs, the donkey). Found: today’s hidden stashes on this street.": "धमाल: आपके पटाखों की शरारत के अंक (लोगों, दुकानों, छतों, गधे के पास)। मिले: इस गली में आज के छिपे माल।",
