  "🗝 Find the 9 key pieces, then steal the {0}! The clock starts with your first step": "🗝 9 चाबी के टुकड़े ढूँढो, फिर {0} चुराओ! घड़ी आपके पहले क़दम से चलेगी",
  "💞 Romantic": "💞 रोमांटिक",
  "😘 Flirty": "😘 नटखट",
  "🥰 Sweet": "🥰 प्यारा",
  "😂 Funny": "😂 मज़ेदार",
  "🙏 Grateful": "🙏 आभार",
  "Out of every sky I've seen, you're still the brightest light in mine.": "जितने आसमान देखे, उनमें सबसे चमकती रोशनी आज भी तुम हो।",
  "I love that home stopped being a place the day it became you.": "मुझे अच्छा लगता है कि घर एक जगह नहीं रहा, जिस दिन वह तुम बन गए।",
  "Every firework fades. What I feel for you only gets louder.": "हर आतिशबाज़ी बुझ जाती है। तुम्हारे लिए मेरा प्यार और ऊँचा होता जाता है।",
  "I'd choose you on every Diwali, in every lifetime.": "हर दिवाली, हर जन्म में मैं तुम्हें ही चुनूँगा।",
  "You're the reason ordinary nights feel like festivals.": "तुम्हारी वजह से आम रातें भी त्योहार लगती हैं।",
  "I love you because with you, even silence feels like…": "मैं तुमसे प्यार करता हूँ क्योंकि तुम्हारे साथ ख़ामोशी भी लगती है…",
  "Warning: you make my heart burst louder than a thousand-wala.": "सावधान: तुम मेरे दिल को हज़ार लड़ी से भी ज़ोर से धड़काते हो।",
  "Are you a sparkler? You light me up every time you smile.": "क्या तुम फुलझड़ी हो? तुम्हारी हर मुस्कान मुझे रोशन कर देती है।",
  "I lost my words the first time you smiled. Still looking for them.": "पहली बार तुम्हें मुस्कुराते देखा, मेरे शब्द खो गए। अब तक ढूँढ रहा हूँ।",
  "You, me and a rooftop full of fireworks. Say yes?": "तुम, मैं और आतिशबाज़ी से भरी छत। हाँ कहोगे?",
  "My favourite view tonight isn't the fireworks. It's you.": "आज रात मेरा पसंदीदा नज़ारा आतिशबाज़ी नहीं, तुम हो।",
  "The first thing I noticed about you was…": "तुम्हारे बारे में सबसे पहले मैंने देखा…",
  "You make my bad days shorter and my good days shine.": "तुम मेरे बुरे दिन छोटे और अच्छे दिन चमकदार बना देते हो।",
  "I love the way you laugh before you finish your own jokes.": "मुझे अच्छा लगता है जब तुम अपना ही चुटकुला ख़त्म होने से पहले हँस पड़ते हो।",
  "Thank you for being my safe place in a noisy world.": "इस शोर भरी दुनिया में मेरी सुरक्षित जगह बनने के लिए शुक्रिया।",
  "Your hug is my favourite place to be.": "तुम्हारी झप्पी मेरी सबसे पसंदीदा जगह है।",
  "With you, every day is a little Diwali.": "तुम्हारे साथ हर दिन एक छोटी दिवाली है।",
  "I love the little things you do, like…": "मुझे तुम्हारी छोटी-छोटी बातें पसंद हैं, जैसे…",
  "I love you more than free gems. And that's a lot.": "मैं तुमसे मुफ़्त रत्नों से भी ज़्यादा प्यार करता हूँ। और वह बहुत है।",
  "You're my favourite notification.": "तुम मेरा सबसे पसंदीदा नोटिफ़िकेशन हो।",
  "I love you even when you steal the last laddoo.": "आख़िरी लड्डू चुराने पर भी मैं तुमसे प्यार करता हूँ।",
  "You're the only one I'd share my phuljhari with.": "अपनी फुलझड़ी मैं सिर्फ़ तुम्हारे साथ बाँटूँगा।",
  "Life with you is like a cracker: loud, bright and a little dangerous.": "तुम्हारे साथ ज़िंदगी पटाखे जैसी है: तेज़, चमकदार और थोड़ी ख़तरनाक।",
  "I love you because you laugh at my worst jokes, like…": "मैं तुमसे प्यार करता हूँ क्योंकि तुम मेरे सबसे बुरे चुटकुलों पर भी हँसते हो, जैसे…",
  "Amma, every light in my life started with you.": "अम्मा, मेरी ज़िंदगी की हर रोशनी तुमसे शुरू हुई।",
  "Thank you for believing in me before I believed in myself.": "मुझ पर तब भरोसा करने के लिए शुक्रिया, जब मुझे ख़ुद पर नहीं था।",
  "You gave me roots, and then you gave me wings.": "तुमने मुझे जड़ें दीं, फिर पंख दिए।",
  "Friends like you make every festival feel like home.": "तुम जैसे दोस्त हर त्योहार को घर जैसा बना देते हैं।",
  "Whatever I become, it began with your love.": "मैं जो भी बनूँ, उसकी शुरुआत तुम्हारे प्यार से हुई।",
  "I'm grateful for you because…": "मैं तुम्हारा आभारी हूँ क्योंकि…",
  "Reasons to love": "प्यार की वजहें",
  "✨ Surprise me with a reason": "✨ कोई वजह चुनकर दिखाओ",
  "Give them a reason to love you back. Pick a line, make it yours, then send it.": "उन्हें वापस प्यार करने की वजह दो। एक पंक्ति चुनें, उसे अपना बनाएँ, फिर भेजें।",
  "💌 Posted! Now make it unforgettable:": "💌 पोस्ट हो गया! अब इसे यादगार बनाएँ:",
  "🎆 Light it in the sky": "🎆 इसे आसमान में जगमगाएँ",
  "💬 Share the note": "💬 संदेश शेयर करें",
  "The sky show is recorded: share the video at the end.": "आसमान का शो रिकॉर्ड होता है: आख़िर में वीडियो शेयर करें।",
  "Light it in the sky": "इसे आसमान में जगमगाएँ",
  "✓ Video saved · record again": "✓ वीडियो सेव हुआ · फिर रिकॉर्ड करें",
