  "💖 I Love You": "💖 आई लव यू",
  "🪔 Happy Diwali": "🪔 शुभ दीपावली",
  "🙏 Thank You": "🙏 धन्यवाद",
  "Light it as:": "इस रूप में जगमगाएँ:",
  "Free skies, bright hearts. Happy Independence Day! Jai Hind!": "आज़ाद आसमान, रोशन दिल। जय हिंद!",
  "Happy Independence Day! You taught me to love this country and stand tall.": "स्वतंत्रता दिवस की शुभकामनाएँ! आपने मुझे इस देश से प्यार करना और सिर ऊँचा रखना सिखाया।",
  "Happy Independence Day! Thank you for the stories of the freedom you lived through.": "स्वतंत्रता दिवस की शुभकामनाएँ! आपकी देखी आज़ादी की कहानियों के लिए शुक्रिया।",
  "Happy Independence Day! Free to dream, and dreaming with you.": "स्वतंत्रता दिवस की शुभकामनाएँ! सपने देखने की आज़ादी, और तुम्हारे साथ सपने।",
  "Happy Independence Day! May you grow up proud, free and kind.": "स्वतंत्रता दिवस की शुभकामनाएँ! तुम गर्व, आज़ादी और दया के साथ बड़े हो।",
  "Happy Independence Day! Kites, flags and you: the best kind of holiday.": "स्वतंत्रता दिवस की शुभकामनाएँ! पतंगें, झंडे और तुम: सबसे अच्छी छुट्टी।",
  "Happy Independence Day to our whole family! Jai Hind!": "स्वतंत्रता दिवस की शुभकामनाएँ! हमारे पूरे परिवार को! जय हिंद!",
  "Happy Independence Day, friend! Here’s to freedom, and to us.": "स्वतंत्रता दिवस की शुभकामनाएँ! दोस्त, आज़ादी के नाम, और हमारे नाम।",
  "Happy Independence Day! Thank you for teaching us to think freely.": "स्वतंत्रता दिवस की शुभकामनाएँ! आज़ाद सोचना सिखाने के लिए शुक्रिया।",
  "Happy Independence Day to the team! Proud to build with you.": "स्वतंत्रता दिवस की शुभकामनाएँ! पूरी टीम को! आपके साथ बनाने पर गर्व है।",
  "Happy Independence Day! Free skies, bright hearts, and you in mine.": "स्वतंत्रता दिवस की शुभकामनाएँ! आज़ाद आसमान, रोशन दिल, और मेरे दिल में तुम।",
  "Tricolour": "तिरंगा",
  "Write your note first 💌": "पहले अपना संदेश लिखें 💌",
  "Ten notes a day. Tap Post again for one more: 💎{0}": "रोज़ दस संदेश। एक और के लिए फिर से पोस्ट दबाएँ: 💎{0}",
  "Three notes a day free (ten with Premium). Tap Post again for one more: 💎{0}": "रोज़ तीन संदेश मुफ़्त (प्रीमियम के साथ दस)। एक और के लिए फिर से पोस्ट दबाएँ: 💎{0}",
  "an extra love note": "एक और प्यार भरा संदेश",
  "Light it as (the heading written in fireworks):": "इस रूप में जगमगाएँ (आतिशबाज़ी में लिखा शीर्षक):",
  "✨ Make it unforgettable:": "✨ इसे यादगार बनाएँ:",
  "{0} The {1} is still in Seth-ji's vault": "{0} {1} अभी भी सेठजी की तिजोरी में है",
  "Find the 9 key pieces and steal it before the week ends": "9 चाबी के टुकड़े ढूँढो और हफ़्ता ख़त्म होने से पहले चुराओ",
  "🪔 Today’s Diya Path puzzle is waiting": "🪔 आज की दीया पथ पहेली इंतज़ार कर रही है",
  "A new board for everyone. Can you solve it in fewer moves?": "सबके लिए नया बोर्ड। क्या आप कम चालों में हल कर सकते हैं?",
  "🎯 Four new goals today": "🎯 आज चार नए लक्ष्य",
  "Two are about the people you love. Claim the gems before midnight": "दो आपके अपनों के लिए हैं। आधी रात से पहले रत्न लें",
  "💌 Someone could use a love note tonight": "💌 आज रात किसी को प्यार भरे संदेश की ज़रूरत है",
  "Pick a reason to love, light it in the sky, and send the video": "प्यार की एक वजह चुनें, आसमान में जगमगाएँ, और वीडियो भेजें",
  "🛕 Fireworks with friends tonight?": "🛕 आज रात दोस्तों के साथ आतिशबाज़ी?",
  "Up to four at a temple on Mela Night. Most hearts wins": "मेला नाइट में एक मंदिर में चार तक। सबसे ज़्यादा दिल जीतता है",
  "You hold the week's best heist: {0}. Defend it!": "इस हफ़्ते की सबसे तेज़ चोरी आपकी है: {0}। इसे बचाएँ!",
  "{0} stole the {1} in {2}": "{0} ने {1} {2} में चुराया",
